// Tasa efectiva importadores = oficial diario BCB + spread bancario.
// Parser en 3 niveles: (1) selector exacto del widget del BCB
// (<span class="bcb-tco-num">9,83</span>), (2) heuristica rango 9-12,
// (3) OFICIAL_MANUAL editable. Verificado contra bcb.gob.bo el 04-jul-2026.
const OFICIAL_MANUAL = { valor: 9.83, vigenteDesde: '2026-07-04', nota: 'ultimo valor confirmado a mano' };
const SPREAD_BANCARIO = 0.10;

let referencia = null;
try {
  const data = $('Binance P2P USDT BOB').first().json;
  const prices = (data.data || [])
    .map((row) => Number(row?.adv?.price))
    .filter((p) => Number.isFinite(p) && p > 0)
    .sort((a, b) => a - b);
  if (prices.length) referencia = prices[Math.floor(prices.length / 2)];
} catch (e) { /* sin binance */ }

let oficial = null;
let fuente = null;
let fechaBcb = null;
try {
  const raw = $('BCB oficial diario').first().json;
  const html = String(raw.data ?? raw.body ?? JSON.stringify(raw));
  // Nivel 1: selector exacto del widget oficial
  const exact = html.match(/bcb-tco-num[^>]*>\s*([0-9]{1,2})[.,]([0-9]{2})\s*</);
  if (exact) {
    const v = Number(exact[1] + '.' + exact[2]);
    if (v >= 6 && v <= 20) { oficial = v; fuente = 'BCB widget oficial'; }
  }
  const fecha = html.match(/is-tc-oficial[\s\S]{0,600}?datetime="([0-9-]+)"/);
  if (fecha) fechaBcb = fecha[1];
  // Nivel 2: heuristica de frecuencia en rango plausible
  if (!oficial) {
    const candidates = [];
    const rx = /(9|1[01])[.,]([0-9]{2})/g;
    let m;
    while ((m = rx.exec(html)) !== null) {
      const v = Number(m[1] + '.' + m[2]);
      if (v >= 9.0 && v <= 12.0) candidates.push(v);
    }
    if (candidates.length >= 2) {
      const freq = {};
      for (const c of candidates) freq[c] = (freq[c] || 0) + 1;
      const top = Object.entries(freq).sort((a, b) => b[1] - a[1])[0];
      if (top[1] >= 2) { oficial = Number(top[0]); fuente = 'BCB heuristica'; }
    }
  }
} catch (e) { /* BCB caido */ }

// Nivel 3: manual
if (!oficial) { oficial = OFICIAL_MANUAL.valor; fuente = 'manual (' + OFICIAL_MANUAL.nota + ')'; }

const efectiva = oficial + SPREAD_BANCARIO;
const fecha = new Date().toLocaleDateString('es-BO', { timeZone: 'America/La_Paz', day: '2-digit', month: '2-digit', year: 'numeric' });

const lineas = [
  'Tipo de cambio Bolivia - ' + fecha,
  '',
  'Oficial BCB' + (fechaBcb ? ' (' + fechaBcb + ')' : '') + ': ' + oficial.toFixed(2) + ' Bs [' + fuente + ']',
  'TASA EFECTIVA (+' + SPREAD_BANCARIO.toFixed(2) + ' banco): ' + efectiva.toFixed(2) + ' Bs  <- esta mueve precios',
  referencia ? 'Referencia Binance P2P: ' + referencia.toFixed(2) + ' Bs (no usable via bancos)' : 'Referencia Binance: no disponible',
  '',
  'Cambio de tasa => repreciar con aprobacion del dueno.'
];

return [{ json: { text: lineas.join('\n'), oficial, fuente, fechaBcb, spread: SPREAD_BANCARIO, tasaEfectiva: efectiva, referenciaBinance: referencia } }];
